        return '0' if digit == '9' else str(int(digit) + 1)

    def decrement_digit(digit):
        return '9' if digit == '0' else str(int(digit) - 1)

    def is_valid_time(hh, mm):
        return 0 <= int(hh) <= 23 and 0 <= int(mm) <= 59

    def generate_neighbors(time):
        hh, mm = time[:2], time[3:]
        neighbors = []
        for i in range(4):
            for direction in [-1, 1]:
                if i < 2:
                    new_hh = hh[:i] + (increment_digit(hh[i]) if direction == 1 else decrement_digit(hh[i])) + hh[i+1:]
                    if is_valid_time(new_hh, mm):
                        neighbors.append(new_hh + ':' + mm)
                else:
                    new_mm = mm[:i-2] + (increment_digit(mm[i-2]) if direction == 1 else decrement_digit(mm[i-2])) + mm[i-1:]
                    if is_valid_time(hh, new_mm):
                        neighbors.append(hh + ':' + new_mm)
        return neighbors

    from collections import deque

