            yield "".join(current_hours + current_minutes)

    def generate_paths(start, end):
        seen_times = set()
        forward_changes = list(change_time(start, end, 1))
        backward_changes = list(change_time(start, end, -1))
        all_changes = [start] + forward_changes + backward_changes + [end]

        for change in all_changes:
            if change not in seen_times:
                seen_times.add(change)
        return seen_times

